import{_ as o,C as r,o as d,c as s,aj as e,E as n}from"./framework.js";const k=JSON.parse('{"title":"基础 · 高级 Tab | Cms / Settings / Basic | Documentation","description":"面向开发与运维的 底层开关：默认关系型数据库、k.DB.sql 指向、SQL 日志 与 代码日志、保存时约束修复、Hook 总开关、断点续传下载，以及站点 自定义键值 设置。","frontmatter":{"title":"基础 · 高级 Tab | Cms / Settings / Basic | Documentation","description":"面向开发与运维的 底层开关：默认关系型数据库、k.DB.sql 指向、SQL 日志 与 代码日志、保存时约束修复、Hook 总开关、断点续传下载，以及站点 自定义键值 设置。","head":[["link",{"rel":"canonical","href":"https://docs.kooboo.com/zh/cms/settings/basic/advanced.html"}]]},"headers":[],"relativePath":"zh/cms/settings/basic/advanced.md","filePath":"cms/settings/basic/advanced.md","lastUpdated":1780899944000}'),c={name:"zh/cms/settings/basic/advanced.md"};function l(i,t,h,g,b,m){const a=r("DocImage");return d(),s("div",null,[t[0]||(t[0]=e('<h1 id="基础-·-高级-tab" tabindex="-1">基础 · 高级 Tab <a class="header-anchor" href="#基础-·-高级-tab" aria-label="Permalink to &quot;基础 · 高级 Tab&quot;">​</a></h1><blockquote><p>Tab：<strong>高级</strong> · <code>name=advance</code><br> 深链：<code>/_Admin/system/settings?SiteId={站点GUID}&amp;name=advance</code></p></blockquote><p>面向开发与运维的 <strong>底层开关</strong>：默认关系型数据库、<code>k.DB.sql</code> 指向、<strong>SQL 日志</strong> 与 <strong>代码日志</strong>、保存时约束修复、<strong>Hook</strong> 总开关、断点续传下载，以及站点 <strong>自定义键值</strong> 设置。</p>',3)),n(a,{src:"/cms/settings/settings-basic-advanced.png",alt:"高级 Tab",width:"1120"}),t[1]||(t[1]=e('<h2 id="默认数据库" tabindex="-1">默认数据库 <a class="header-anchor" href="#默认数据库" aria-label="Permalink to &quot;默认数据库&quot;">​</a></h2><p><strong>默认数据库</strong>（<code>defaultDatabase</code>）决定 <code>k.DB.sql</code> 解析到哪一套关系型库：</p><table tabindex="0"><thead><tr><th>值</th><th>说明</th></tr></thead><tbody><tr><td><strong>Auto</strong></td><td>自动：优先级 <strong>MySQL &gt; SQL Server &gt; SQLite</strong>（须在 <a href="./../integrations/">服务集成</a> 配好连接）</td></tr><tr><td><strong>Sqlite</strong> / <strong>Mysql</strong> / <strong>SqlServer</strong></td><td>固定指向对应库</td></tr></tbody></table><p>详见 <a href="/kb-docs/zh/api/database/">k.DB</a> 与 <a href="./../../database/">数据库</a> 各表篇。</p><h2 id="sql-日志" tabindex="-1">SQL 日志 <a class="header-anchor" href="#sql-日志" aria-label="Permalink to &quot;SQL 日志&quot;">​</a></h2><p><strong>SQL 日志</strong>（<code>enableSqlLog</code>）：与 <a href="./../../database/sql-logs.html">数据库 → SQL 日志</a> 页右侧开关 <strong>等价</strong>，控制是否记录 <code>k.DB.sqlite</code> / <code>mysql</code> / <code>sqlServer</code> 的 SQL。</p><h2 id="代码日志" tabindex="-1">代码日志 <a class="header-anchor" href="#代码日志" aria-label="Permalink to &quot;代码日志&quot;">​</a></h2><p>分组 <strong>代码日志</strong>（<code>codeLogSettings</code>）：</p><table tabindex="0"><thead><tr><th>字段</th><th>说明</th></tr></thead><tbody><tr><td><strong>启用</strong></td><td>是否记录 KScript 代码日志</td></tr><tr><td><strong>级别</strong></td><td>Debug / Information / Warning / Error / Critical</td></tr><tr><td><strong>保留天数</strong></td><td>日志保留 <code>keepDays</code>（≥1）</td></tr></tbody></table><p>列表查询见 <a href="./../../development/code-log.html">开发 → 代码日志</a>。</p><h2 id="约束与其它开关" tabindex="-1">约束与其它开关 <a class="header-anchor" href="#约束与其它开关" aria-label="Permalink to &quot;约束与其它开关&quot;">​</a></h2><table tabindex="0"><thead><tr><th>开关</th><th>说明</th></tr></thead><tbody><tr><td><strong>保存时约束修复</strong></td><td><code>enableConstraintFixOnSave</code>：保存内容等资源时自动修复部分约束冲突</td></tr><tr><td><strong>请求 Hook</strong></td><td><code>enableFrontEvents</code>：是否启用 <a href="./../request-hooks.html">请求 Hook</a> 机制（仍须在 Hook 页配置具体规则）</td></tr><tr><td><strong>操作 Hook</strong></td><td><code>enableBackendEvents</code>：是否启用 <a href="./../action-hooks.html">操作 Hook</a></td></tr><tr><td><strong>断点续传下载</strong></td><td><code>continueDownload</code>：大文件下载续传（部分环境显示）</td></tr></tbody></table><h2 id="自定义设置" tabindex="-1">自定义设置 <a class="header-anchor" href="#自定义设置" aria-label="Permalink to &quot;自定义设置&quot;">​</a></h2><p><strong>自定义设置</strong>（<code>customSettings</code>）：键值对编辑器，供站点或模块读取的扩展配置（<code>KeyValueEditor</code>）。键名须符合产品约定；脚本可通过站点 API 或约定名访问，勿与 <a href="./../../database/key-value.html">键值存储</a>（<code>k.DB.keyValue</code>）混淆。</p><h2 id="相关" tabindex="-1">相关 <a class="header-anchor" href="#相关" aria-label="Permalink to &quot;相关&quot;">​</a></h2><ul><li><a href="./">基础设置概述</a></li><li><a href="./../../database/sql-logs.html">SQL 日志</a></li><li><a href="./../integrations/">服务集成</a>（Database 连接）</li></ul>',16))])}const u=o(c,[["render",l]]);export{k as __pageData,u as default};
